// List all monitored services with their types
fetch dt.entity.service
| fieldsAdd entity.name, serviceType
| sort entity.name asc
| limit 25

// Smartscape equivalent (dt.entity.* is deprecated but still functional):
//   smartscapeNodes "SERVICE"
//   | fieldsAdd name, dt.service.sdv1_type
//   | sort name asc
//   | limit 25
// Caveat: Smartscape reflects CURRENT live topology and can report fewer entities than
// the classic entity store; for a pre-migration discovery inventory keep the classic query above.
// Field maps: serviceType -> dt.service.sdv1_type; entity.name -> name.

// Count error logs in the last hour by log level
fetch logs, from:-1h
| summarize log_count = count(), by:{loglevel}
| sort log_count desc

// Top 5 hosts by CPU usage in the last hour
timeseries cpuUsage = avg(dt.host.cpu.usage), from:-1h, by:{dt.entity.host}
| fieldsAdd avgCpu = arrayAvg(cpuUsage)
| sort avgCpu desc
| limit 5

// Log ingestion volume over the last 24 hours by source
fetch logs, from:-24h
| summarize record_count = count(), by:{log.source}
| sort record_count desc
| limit 10
